def _fbits(value: float) -> int:
    return struct.unpack("<I", struct.pack("<f", value))[0]


def _matrix_bytes(m) -> bytes:
    return b"".join(struct.pack("<I", _fbits(v)) for v in m)


def _record(case) -> bytes:
    a, b, radius, matrix = case
    rec = bytearray(0x24)
    for i, v in enumerate(a):
        struct.pack_into("<I", rec, i * 4, _fbits(v))
    for i, v in enumerate(b):
        struct.pack_into("<I", rec, 0x10 + i * 4, _fbits(v))
    struct.pack_into("<I", rec, 0x20, _fbits(radius))
    return bytes(rec)


def make_args(i: int) -> List[ArgSpec]:
    case = CASES[i % len(CASES)]
    args = [
        ArgSpec(kind="ptr", mem=_record(case), arena_offset=RECORD_OFF),
        ArgSpec(kind="ptr", mem=bytes(32), arena_offset=OUT_OFF),
        ArgSpec(kind="ptr", mem=_matrix_bytes(case[-1]), arena_offset=MATRIX_OFF),
    ]
    return args
